function findText(t) {
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, null);
  const results = [];
  let node;
  while ((node = walker.nextNode())) {
    if (node.nodeValue.includes(t)) {
      let parent = node.parentElement;
      while (parent && results.indexOf(parent) === -1) {
        if (parent.textContent.length < 500) results.push(parent);
        break;
      }
    }
  }
  return results.map(p => p.tagName + ': ' + p.textContent.trim().substring(0, 300));
}
return findText('chip') + '\n---\n' + findText('A17') + '\n---\n' + findText('$');

