const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, null);
const chips = [];
let node;
while ((node = walker.nextNode())) {
  const text = node.nodeValue;
  if (text.includes('A16') || text.includes('A17') || text.includes('Bionic') || text.includes('A20')) {
    let parent = node.parentElement;
    while (parent && parent.textContent.length > 500) parent = parent.parentElement;
    if (parent && chips.indexOf(parent.textContent.trim()) === -1) {
      chips.push(parent.textContent.trim().substring(0, 300));
    }
  }
}
return chips.join('\n----\n');

const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, null);
const prices = [];
let node;
while ((node = walker.nextNode())) {
  const text = node.nodeValue;
  if (text.includes('$') || text.includes('From ') || text.toLowerCase().includes('price')) {
    let parent = node.parentElement;
    while (parent && parent.textContent.length > 200) parent = parent.parentElement;
    if (parent && prices.indexOf(parent.textContent.trim()) === -1) {
      prices.push(parent.textContent.trim().substring(0, 200));
    }
  }
}
return prices.join('\n');
